const {chromium}=require('playwright');const assert=require('node:assert/strict');
async function main(){const {createServer}=await import('vite');const server=await createServer({server:{host:'127.0.0.1',port:4301,strictPort:true}});await server.listen();const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_EXECUTABLE_PATH||undefined,args:['--no-sandbox']});
try{for(const width of [390,768,1024,1440])for(const theme of ['light','dark']){const context=await browser.newContext({viewport:{width,height:900},colorScheme:theme});const page=await context.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.addInitScript(()=>{window.__printed=[];const original=window.open.bind(window);window.open=(...args)=>{const output=original(...args);if(output)output.print=()=>window.__printed.push(output.document.body.innerText);return output;};});
await page.goto('http://127.0.0.1:4301/#/app/daybook');await page.getByRole('heading',{name:'Daybook',exact:true}).waitFor();const count=await page.locator('main tbody tr').count();assert.ok(count>0);
const popup=page.waitForEvent('popup');await page.getByRole('button',{name:'Print',exact:true}).click();const print=await popup;await page.waitForFunction(()=>window.__printed.length===1);assert.ok((await print.locator('tbody tr').count())===count,'prints current rows only');assert.match(await print.locator('body').innerText(),/Money in/);await print.close();
await page.getByRole('button',{name:/Actions for/}).first().click();await page.getByRole('button',{name:'Review reversal',exact:true}).click();await page.getByText(/cannot reverse a source by deleting/).waitFor();await page.getByRole('button',{name:'Cancel',exact:true}).click();assert.equal(await page.locator('main tbody tr').count(),count,'no projection-only delete');
const downloaded=page.waitForEvent('download');await page.getByRole('button',{name:'Export',exact:true}).click();assert.equal((await downloaded).suggestedFilename(),'hisabiq-daybook.csv');
await page.goto('http://127.0.0.1:4301/#/app/audit-ledger');await page.getByRole('heading',{name:'Audit Ledger',exact:true}).waitFor();const auditPopup=page.waitForEvent('popup');await page.getByRole('button',{name:'Print',exact:true}).click();const auditPrint=await auditPopup;await page.waitForFunction(()=>window.__printed.length===2);assert.match(await auditPrint.locator('body').innerText(),/Audit Ledger/);assert.ok(await auditPrint.locator('tbody tr').count()>0);await auditPrint.close();assert.deepEqual(errors,[]);await context.close();}
console.log('Day Book/Audit isolated filtered print, real export and source-review reversal with unchanged rows passed at four sizes in light/dark');}finally{await browser.close();await server.close();}}
main().catch(error=>{console.error(error);process.exitCode=1;});
